import{Tt as e,at as t,rt as n,t as r}from"./chunks/framework.j55wycBY.js";var i=JSON.parse(`{"title":"Documentation previews","description":"","frontmatter":{},"headers":[],"relativePath":"developer/docs-previews.md","filePath":"developer/docs-previews.md"}`),a={name:`developer/docs-previews.md`};function o(r,i,a,o,s,c){return e(),n(`div`,{"data-pagefind-body":!0,"data-pagefind-meta":`date:1795876923000`},[...i[0]||=[t(`<h1 id="documentation-previews" tabindex="-1">Documentation previews <a class="header-anchor" href="#documentation-previews" aria-label="Permalink to “Documentation previews”">​</a></h1><p>CI builds affected documentation for pull requests. Same-repository pull requests, except Dependabot pull requests, also receive a preview link. Fork and Dependabot pull requests are validated without publishing.</p><p>Production and previews share the <code>gh-pages</code> branch. The dedicated cleanup workflow runs on a schedule or manually. It removes preview directories whose most recent Git commit author timestamp is more than seven days old, even if the pull request is still open. A subsequent update recreates a removed preview; an unchanged deployment does not refresh its timestamp. Cleanup attempts to update the corresponding PR comment.</p><h2 id="local-docs" tabindex="-1">Local docs <a class="header-anchor" href="#local-docs" aria-label="Permalink to “Local docs”">​</a></h2><p>Run <code>nx dev docs</code> for VitePress and the REST reference. Restart it after editing an OpenAPI spec to rebuild the bundle and refresh endpoint routes and Markdown. For the standalone Scalar explorer, run <code>nx dev api-web</code>.</p><p>Run <code>nx preview docs</code> to build and serve the full artifact, including Scalar and the REST Markdown. The default base is <code>/notopia/</code>; set <code>DOCS_BASE=/notopia/pr/123/</code> to preview a PR base.</p>`,6)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};